from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    exterior = set()
    q = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == background and (r, c) not in exterior:
                exterior.add((r, c))
                q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == background and (r, c) not in exterior:
                exterior.add((r, c))
                q.append((r, c))
    while q:
        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if (0 <= nr < h and 0 <= nc < w and
                    grid[nr][nc] == background and (nr, nc) not in exterior):
                exterior.add((nr, nc))
                q.append((nr, nc))
    for r in range(h):
        for c in range(w):
            if grid[r][c] == background and (r, c) not in exterior:
                out[r][c] = 4
    return out


